<script lang="ts">
  import type {PageData} from './$types';
  let {data}:{data:PageData}=$props();
  import {enhance} from '$app/forms';
  import {useI18n} from '$lib/i18n';
  const {t,locale}=useI18n();
  const fmt=(d:string)=>new Date(d).toLocaleDateString(locale,{day:'numeric',month:'short',year:'numeric'});
  const time=(ms:number)=>`${Math.floor(ms/60000)}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}`;
</script>
<div class="main"><header class="row" style="justify-content:space-between"><a href="/dashboard">{t('proj.back')}</a><a href={`/p/${data.project.slug}`} class="pill">{t('proj.link')}</a></header><div class="eyebrow" style="margin-top:45px">{t('proj.eyebrow',{status:data.project.status})}</div><h1 style="font-size:clamp(2.4rem,6vw,4rem)">{data.project.title}</h1><p class="muted" style="font-size:1.2rem">{data.project.question}</p><div class="row" style="flex-wrap:wrap;margin:24px 0"><a class="btn" href={`/p/${data.project.slug}`}>{t('proj.startRec')}</a><a class="btn secondary" href={`/dashboard/projects/${data.project.id}/nodes`}>{t('proj.map')}</a><a class="btn secondary" href={`/dashboard/projects/${data.project.id}/reels`}>{t('proj.reels')}</a><button class="btn secondary" onclick={()=>navigator.clipboard.writeText(`${location.origin}/p/${data.project.slug}`)}>{t('proj.copyLink')}</button></div>
<form method="POST" action="?/setMode" use:enhance={()=>async({update})=>update({reset:false})} class="row" style="flex-wrap:wrap;margin-bottom:18px"><label class="tiny">{t('dash.mode')} <select class="field" name="capture_mode" value={data.project.capture_mode} onchange={(e)=>e.currentTarget.form?.requestSubmit()}><option value="video">{t('mode.video')}</option><option value="audio">{t('mode.audio')}</option><option value="either">{t('mode.either')}</option></select></label></form>
<section class="grid"><div class="panel"><div class="eyebrow">{t('proj.videos')}</div><div class="big-number">{data.sources.length}</div></div><div class="panel"><div class="eyebrow">{t('proj.themes')}</div><div class="big-number">{data.themes.length}</div></div><div class="panel"><div class="eyebrow">{t('proj.highlightSuggestions')}</div><div class="big-number">{data.highlights.length}</div></div></section>
{#if data.report && data.report.report && typeof data.report.report==='object'}<section class="panel" style="margin-top:18px"><div class="eyebrow">{t('proj.lastReport')}</div><h2>{t('proj.noticed')}</h2><p class="muted">{(data.report.report as {latestSourceSummary?:string}).latestSourceSummary??t('proj.noSummary')}</p><small class="muted">{t('proj.reportNote')}</small></section>{/if}
<section class="grid" style="margin-top:18px"><div class="panel"><h2>{t('proj.detected')}</h2>{#if data.themes.length}{#each data.themes as th}<div class="row" style="justify-content:space-between;border-bottom:2px solid #000;padding:10px 0"><span>{th.name}{#if th.description}<br><small class="muted">{th.description}</small>{/if}</span><span class="muted">{t('proj.sources',{n:th.source_count})}</span></div>{/each}{:else}<p class="muted">{t('proj.themesLater')}</p>{/if}</div><div class="panel"><h2>{t('proj.recordings')}</h2>{#if !data.sources.length}<p class="muted">{t('proj.noContrib')}</p>{/if}{#each data.sources as s}<div style="padding:14px 0;border-bottom:2px solid #000"><strong>{s.title}</strong> <span class="pill">{s.status}</span> <small class="muted">{fmt(s.created_at)}</small>{#if s.stale}<form method="POST" action="?/reprocess" use:enhance style="display:inline"><input type="hidden" name="sourceId" value={s.id}><button class="btn secondary" type="submit" title={t('proj.reprocessHint')}>{t('proj.reprocess')}</button></form>{/if}{#if s.status==='ready'}<video controls preload="metadata" playsinline src={`/api/dashboard/media/${s.id}`} style="display:block;margin-top:12px;border-radius:10px;max-height:220px"></video>{/if}{#if s.analysis && typeof s.analysis==='object'}<p class="muted tiny">{(s.analysis as {summary?:string}).summary??''}</p>{/if}<p class="tiny muted">{s.id}</p></div>{/each}</div></section>
<section class="panel" style="margin-top:18px"><h2>{t('proj.highlights')}</h2><p class="muted tiny">{t('proj.highlightsNote')}</p>{#if data.highlights.length===0}<p class="muted">{t('proj.highlightsEmptyA')} `npm run render -- &lt;highlight-id&gt;`.</p>{/if}{#each data.highlights as h}<div style="padding:16px 0;border-bottom:2px solid #000"><strong>{h.title}</strong> · <span class="muted">{Array.isArray(h.clips)&&h.clips.length>0?t('proj.clips',{n:h.clips.length})+' · ':time(h.start_ms)+'–'+time(h.end_ms)+' · '}{h.status}</span><p class="muted">{h.reason}</p>{#if h.status==='suggested'}<form method="POST" action="?/approveHighlight"><input type="hidden" name="highlightId" value={h.id}/><button class="btn secondary" style="margin:10px 0">{t('proj.approve')}</button></form>{/if}{#if h.status==='rendered'}<video controls playsinline preload="metadata" src={`/api/dashboard/highlight/${h.id}`} style="max-height:300px;border-radius:12px"></video>{/if}</div>{/each}</section>
</div>
